Bash(node -e "
const http = require\('http'\);
const data = JSON.stringify\({email:'admin@futurix.ao',password:'ChangeMe123!'}\);
const req = http.request\({hostname:'localhost',port:3000,path:'/auth/login',method:'POST',headers:{'Content-Type':'application/json','Content-Length':data.length}}, \(res\) => {
  let body='';
  res.on\('data',c=>body+=c\);
  res.on\('end',\(\)=>{
    const token = JSON.parse\(body\).accessToken;
    const req2 = http.request\({hostname:'localhost',port:3000,path:'/admin/stats',method:'GET',headers:{'Authorization':'Bearer '+token}}, \(res2\) => {
      let b='';
      res2.on\('data',c=>b+=c\);
      res2.on\('end',\(\)=>console.log\(res2.statusCode, b\)\);
    }\);
    req2.end\(\);
  }\);
}\);
req.write\(data\);
req.end\(\);
")

